package cc.webrom.wrgram;

import static org.junit.Assert.*;
import org.drinkless.tdlib.TdApi;
import org.junit.Test;

public class BetaPolicyTest {
    @Test public void legacyStorageAndAliasAreUnchanged(){assertEquals("telegram",AccountSlot.directory("primary"));assertEquals("tdlib-key.v1",AccountSlot.envelope("primary"));assertEquals("wrgram.tdlib.database.v1",AccountSlot.alias("primary"));}
    @Test public void otherAccountsHaveIndependentPathsAndAliases(){String slot="1234567890abcdef1234567890abcdef";assertNotEquals(AccountSlot.directory("primary"),AccountSlot.directory(slot));assertNotEquals(AccountSlot.alias("primary"),AccountSlot.alias(slot));assertNotEquals(AccountSlot.envelope("primary"),AccountSlot.envelope(slot));}
    @Test public void slotCannotEscapeStorage(){for(String slot:new String[]{"../telegram","","PRIMARY","a/b","../../keys"})try{AccountSlot.directory(slot);fail(slot);}catch(IllegalArgumentException expected){}}
    @Test public void sixOwnerSuppliedAppsAreBuiltIn(){assertEquals(6,BuiltInApps.ALL.size());assertEquals("GroupButlerEsp_bot",BuiltInApps.require("groupbutler").username);assertEquals("antiubot",BuiltInApps.require("antiu").username);assertEquals("anycompressorbot",BuiltInApps.require("compressor").username);assertEquals("WRShorten_bot",BuiltInApps.require("shorten").username);assertEquals("mutidlprobot",BuiltInApps.require("downloads").username);assertEquals("Wrsnakebot",BuiltInApps.require("snake").username);}
    @Test(expected=IllegalArgumentException.class)public void unknownBotIsNotAnInstalledMiniApp(){BuiltInApps.require("attacker");}
    @Test public void miniAppBridgeIsExactOriginOnly(){assertEquals("https://app.example",MiniAppPolicy.origin("https://app.example/path#signed-data"));assertTrue(MiniAppPolicy.sameOrigin("https://app.example","https://app.example/other"));assertFalse(MiniAppPolicy.sameOrigin("https://app.example","https://app.example.attacker.org"));assertFalse(MiniAppPolicy.sameOrigin("https://app.example","http://app.example"));}
    @Test public void miniAppsCannotLaunchDangerousSchemes(){for(String value:new String[]{"file:///session","javascript:alert(1)","https://user:password@app.example","content://private","http://app.example","https://app.example:8443"})try{MiniAppPolicy.origin(value);fail(value);}catch(IllegalArgumentException expected){}}
    @Test public void bridgeAllowsOnlySpecificNewOperations(){for(String method:new String[]{"accounts.list","accounts.add","accounts.switch","apps.open","apps.profile","chat.secret","sponsored.view","notifications.enable","media.retry"})assertTrue(BridgePolicy.METHODS.contains(method));for(String method:new String[]{"miniapp.eval","bot.token","readChatHistory","accounts.export","tdlib.send"})assertFalse(BridgePolicy.METHODS.contains(method));}
    @Test public void telegramLinksRejectArbitraryHostsAndPrivateSchemes(){assertEquals("https://t.me/example",TelegramLinks.normalize(" https://t.me/example "));assertEquals("tg://resolve?domain=example",TelegramLinks.normalize("tg://resolve?domain=example"));assertNull(TelegramLinks.normalize("https://t.me.example.org/example"));assertNull(TelegramLinks.normalize("http://t.me/example"));assertNull(TelegramLinks.normalize("https://t.me@attacker.example/example"));assertNull(TelegramLinks.normalize("javascript:alert(1)"));}
    @Test public void phonebookImportAcceptsOnlyInternationalNumbers(){assertEquals("+14155550123",NativeBridge.normalizePhonebookNumber("+1 (415) 555-0123"));assertNull(NativeBridge.normalizePhonebookNumber("415-555-0123"));assertNull(NativeBridge.normalizePhonebookNumber("++14155550123"));assertNull(NativeBridge.normalizePhonebookNumber("+123"));}
    @Test public void proxyServersRejectSchemesCredentialsAndPaths(){assertTrue(NativeBridge.validProxyServer("proxy.example.com"));assertTrue(NativeBridge.validProxyServer("2001:db8::1"));assertTrue(NativeBridge.validProxyServer("127.0.0.1"));for(String value:new String[]{"https://proxy.example.com","proxy.example.com/path","user:password@proxy.example.com","proxy example.com",""," ".repeat(3)})assertFalse(value,NativeBridge.validProxyServer(value));assertFalse(NativeBridge.validProxyServer("a".repeat(256)));}
    @Test public void storageOptimizationOnlyUsesConservativeWindows(){assertEquals(7,NativeBridge.storageDays(7));assertEquals(30,NativeBridge.storageDays(30));assertEquals(90,NativeBridge.storageDays(90));assertEquals(30,NativeBridge.storageDays(0));assertEquals(30,NativeBridge.storageDays(45));assertEquals(30,NativeBridge.storageDays(-7));}
    @Test public void pollVoteRestrictionsAreExplainedInSpanish(){assertEquals("La encuesta está cerrada.",NativeSnapshot.pollRestriction(new TdApi.PollVoteRestrictionReasonClosed()));assertEquals("La encuesta aún no se ha enviado.",NativeSnapshot.pollRestriction(new TdApi.PollVoteRestrictionReasonYetUnsent()));assertEquals("La encuesta está programada.",NativeSnapshot.pollRestriction(new TdApi.PollVoteRestrictionReasonScheduled()));assertEquals("Tu país no puede participar en esta encuesta.",NativeSnapshot.pollRestriction(new TdApi.PollVoteRestrictionReasonCountryRestricted()));assertEquals("Debes llevar más de un día en el chat para votar.",NativeSnapshot.pollRestriction(new TdApi.PollVoteRestrictionReasonMembershipRequired()));assertEquals("No puedes votar en esta encuesta.",NativeSnapshot.pollRestriction(new TdApi.PollVoteRestrictionReasonOther()));}
    @Test public void interactiveBatchMethodsAreAllowlisted(){for(String method:new String[]{"poll.send","poll.answer","poll.stop","poll.voters","share.contact","share.location","voice.start","voice.finish","voice.cancel","attachment.videoNote","stickers.installed","stickers.search","stickers.get","stickers.install","proxy.list","proxy.add","proxy.enable","proxy.disable","proxy.remove","proxy.ping","storage.status","storage.optimize"})assertTrue(method,BridgePolicy.METHODS.contains(method));}
    @Test public void messagingBatchMethodsAreAllowlisted(){for(String method:new String[]{"messages.search.more","chat.pinned","message.pin","message.album","message.translate","bot.inline.query","auth.register","auth.recover.request","auth.recover.reset","auth.resend"})assertTrue(method,BridgePolicy.METHODS.contains(method));}
}
